  auto _SPLITTER_ADDRESS = _o->SPLITTER_ADDRESS.empty() ? 0 : _fbb.CreateString(_o->SPLITTER_ADDRESS);
  auto _SPLIT_CONFIG_ID = _o->SPLIT_CONFIG_ID.empty() ? 0 : _fbb.CreateString(_o->SPLIT_CONFIG_ID);
  auto _TOKEN_ADDRESS = _o->TOKEN_ADDRESS.empty() ? 0 : _fbb.CreateString(_o->TOKEN_ADDRESS);
  auto _TOKEN_SYMBOL = _o->TOKEN_SYMBOL.empty() ? 0 : _fbb.CreateString(_o->TOKEN_SYMBOL);
